{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Rifapentine, a close rifamycin analogue (Morgan similarity 0.87) differing mainly in the piperazine N-substituent, has an absolute oral bioavailability of 70% in healthy adult volunteers after a 600 mg tablet dose, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "The 70% oral bioavailability of rifapentine is corroborated in human data and FDA labeling, reinforcing that this rifamycin scaffold is generally well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Rifaximin, a structurally modified rifamycin with a fused heterocycle, has <0.4% oral bioavailability in healthy volunteers; this is contradictory evidence but has lower transferability because the query retains the N-methylpiperazine hydrazone side chain of well-absorbed rifamycins rather than rifaximin's absorption-limiting modification.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is rifampicin, and the closest analogue rifapentine (Morgan 0.87) has absolute oral bioavailability of 70% in humans, strongly supporting a high F >= 20% prediction. The low bioavailability of rifaximin represents a class-specific exception with lower structural transferability and does not override the close analogue evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule was included in the evidence set.",
    "Formulation- and food-dependent effects on oral bioavailability were not systematically assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

